import{_ as o,l as s,o as i,c as n,v as e,p as l,x as t,d as h,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"硬掩模 SiN / TiN","description":"","frontmatter":{"title":"硬掩模 SiN / TiN","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/hardmask-sin-tin.md","filePath":"litho/hardmask-sin-tin.md","lastUpdated":1789023840000}'),E={name:"litho/hardmask-sin-tin.md"};function A(N,a,c,S,T,_){const r=s("Mermaid");return i(),n("div",null,[a[1]||(a[1]=e('<h1 id="硬掩模-sin-tin" tabindex="-1">硬掩模 SiN / TiN <a class="header-anchor" href="#硬掩模-sin-tin" aria-label="Permalink to &quot;硬掩模 SiN / TiN&quot;">​</a></h1><div class="epigraph"><p>薄胶只负责定义边；纵向深度交给更耐打的膜。SiN 与 TiN 一类硬掩模把成像预算和深度预算拆开。</p><footer>—— 对照多层抗蚀剂 / 硬掩模转印的产线通称；[三层 SOC](/litho/trilayer-soc-sog) 已写有机硬掩模栈</footer></div><p><a href="/litho/ler-transfer-smoothing">上一课</a>把边频谱的转印写完。缺口是材料栈：EUV 薄胶和浸没薄胶都不够直接啃厚介质或硅。<a href="/litho/trilayer-soc-sog">三层胶</a> 与 <a href="/litho/rie-pattern-transfer">RIE</a> 已引入硬掩模角色；本课钉 SiN、TiN 在集成里的位置——无机掩模如何改选择比、形貌和计量。各向异性与侧壁钝化，留给[下一课](/litho/anisotropy-passivation）。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>SiN（或 SiO<sub>x</sub>N<sub>y</sub>）常用作接触/浅槽的介电硬掩模；TiN 出现在金属硬掩模（MHM）与某些栅/BEOL 栈。胶先转到硬掩模，再以硬掩模为掩去刻目标。选择比窗口从「胶对目标」变成两段：「胶对硬掩模」×「硬掩模对目标」。每段可单独优化气体，代价是多一步、新缺陷（硬掩模残、金属沾污）和新的 CD 偏置。</p><p>缺口是<strong>为何是这两种膜、以及偏置如何进 OPC</strong>，不是重讲三层涂覆顺序。TiN 不透明或高反射，影响对准与 overlay 标记衬度；SiN 应力影响翘曲（后课晶圆形变）。OPC 核必须声明是对着哪一跳 AEI。</p><h3 id="金属硬掩模的计量陷阱" tabindex="-1">金属硬掩模的计量陷阱 <a class="header-anchor" href="#金属硬掩模的计量陷阱" aria-label="Permalink to &quot;金属硬掩模的计量陷阱&quot;">​</a></h3><p>TiN AEI 的 SEM 衬度、充电与真实硅 AEI 不同。把 MHM CD 当最终电学 CD，会把后续金属填充偏置漏掉。签核轮廓要写「MHM AEI」还是「最终槽」。</p><p><span class="marginnote">硬掩模厚度是 AR 与选择比的旋钮：太薄打穿，太厚开口 AR 升、胶更难转印。厚度均匀性变成全场 CDU 项。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>栈设计：胶 / SiARC 或 SOC / SiN 或 TiN / 目标。每跳食谱独立，成对计量独立校准核。与 BARC open 课衔接：开硬掩模的那一跳往往是 CD 敏感步。TiN 要用无残或可控残的剥离，避免金属污染前道。应力与后续对准：标记设计课已有传感器；本课要求硬掩模开窗策略不毁掉标记。</p><p>OPC 核的 AEI 目标必须写明跳数。混用「开 TiN 后」和「最终槽」两套 SEM，密度斜率会拧反。Levinson 把 ADI/AEI 当合同；硬掩模只是把 AEI 拆成两张合同。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>硬掩模把「成像用薄胶」和「刻穿用厚掩」解耦。第一跳：低 AR、对胶选择比适中。第二跳：高 AR、对硬掩模高选择比、强钝化。CD 偏置是两跳之和，密度核可能要分层。TiN 还可能在等离子体中产金属副产物，改变放电——食谱窗口比 SiN 更脏，颗粒与缺陷检测要跟上。</p>',14)),(i(),l(p,null,{default:t(()=>[d(r,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20PR%5B%22%E8%96%84%E8%83%B6%E8%BE%B9%22%5D%20--%3E%20HM1%5B%22%E5%BC%80%20SiN%20%2F%20TiN%22%5D%0A%20%20HM1%20--%3E%20HM2%5B%22%E7%A1%AC%E6%8E%A9%E6%A8%A1%E5%BD%93%E6%8E%A9%E5%88%BB%E7%9B%AE%E6%A0%87%22%5D%0A%20%20HM2%20--%3E%20FIN%5B%22%E6%9C%80%E7%BB%88%E6%A7%BD%20%2F%20%E5%AD%94%22%5D%0A%20%20HM1%20--%3E%20BIAS%5B%22%E5%81%8F%E7%BD%AE%201%22%5D%0A%20%20HM2%20--%3E%20BIAS2%5B%22%E5%81%8F%E7%BD%AE%202%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[h(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e('<p>两跳偏置必须分账：开硬掩模的 CD 敏感步与最终槽的 AR 步不是同一个核。混报 AEI 会让 OPC 去修错的一跳。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不规定某节点必须用 TiN 或 SiN。不重写 ALD 成膜全文。金属硬掩模与后道集成的污染控制只点名，细节属缺陷课。</p><p>后课默认：深度预算在硬掩模上，胶只定义边。下一课写如何用钝化把硬掩模开口刻直。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>SiN/TiN 把成像与深度拆成两跳选择比，CD 偏置是级联。</li><li>计量轮廓必须声明看到哪一跳。</li><li>应力、反射、金属残是集成税。</li><li>出处：多层硬掩模转印通称；Levinson 流程叙述；三层胶前课。</li></ul>',6))])}const B=o(E,[["render",A]]);export{u as __pageData,B as default};
